import{_ as t,o as a,c as s,ak as i}from"./chunks/framework.CRPHSmau.js";const u=JSON.parse('{"title":"Authentication","description":"","frontmatter":{},"headers":[],"relativePath":"guide/authentication.md","filePath":"guide/authentication.md","lastUpdated":1788857359000}'),n={name:"guide/authentication.md"};function o(r,e,d,l,h,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to “Authentication”">​</a></h1><p>Pika has two distinct authentication mechanisms:</p><ol><li><strong>Sessions</strong> for human users in the web UI (cookie-based).</li><li><strong>API tokens</strong> for programmatic consumers reading <code>/data/*</code> and calling <code>/api/v1/*</code>.</li></ol><p>In addition, pika can plug external identity providers in front of the session login: OAuth2/OIDC or a header-based forward-auth gateway.</p><h2 id="built-in-users" tabindex="-1">Built-in users <a class="header-anchor" href="#built-in-users" aria-label="Permalink to “Built-in users”">​</a></h2><p>Built-in session-based auth is always on. The first time you start the server, the UI shows a setup screen to create the initial admin account. After that, sign in and create more users from <strong>Settings → Users</strong>.</p><p>Each user belongs to one or more <strong>permission bundles</strong> that define which capabilities they hold. Bundles are managed under <strong>Settings → Permissions</strong>.</p><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to “Capabilities”">​</a></h2><p>Users (and externally-authenticated identities) are checked against pika&#39;s capability keys (<code>internal/service/capabilities.go</code> is the source of truth):</p><table tabindex="0"><thead><tr><th>Key</th><th>Grants</th></tr></thead><tbody><tr><td><code>files.read</code></td><td>View folders, files, versions, variants, render and search configurations.</td></tr><tr><td><code>files.write</code></td><td>Create, update and delete folders and configuration files.</td></tr><tr><td><code>external.read</code></td><td>Browse, search and read entries from configured external resources (Vault, Consul, etcd, AWS, Azure, GCP, Kubernetes, HTTP, ...).</td></tr><tr><td><code>external.write</code></td><td>Create, update and delete entries on configured external resources.</td></tr><tr><td><code>settings.manage</code></td><td>View and modify server settings, backup/restore, server encryption-key lifecycle.</td></tr><tr><td><code>tokens.manage</code></td><td>Create, edit, revoke API access tokens.</td></tr><tr><td><code>users.manage</code></td><td>Create, edit, delete, kick users (built-in auth only).</td></tr><tr><td><code>permissions.manage</code></td><td>Define permission bundles and assign them (built-in auth only).</td></tr></tbody></table><p>A bundle can also have an associated <strong>path pattern</strong> that scopes the file/external permissions. For example, a bundle with <code>files.read</code> and pattern <code>team-a/**</code> lets the user read everything under <code>team-a/</code> but nothing else.</p><h2 id="api-tokens" tabindex="-1">API tokens <a class="header-anchor" href="#api-tokens" aria-label="Permalink to “API tokens”">​</a></h2><p>Tokens are the recommended way to authenticate non-human consumers. Mint them under <strong>Settings → Tokens</strong>.</p><p>A token has the format <code>pika_&lt;64hex&gt;</code> and one or more <strong>scopes</strong>. Each scope grants specific operations on a glob-matched path:</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;myapp/**&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;operations&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;read&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;write&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;delete&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Pass the token as a <code>Bearer</code> token:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer pika_...&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  https://localhost:8080/data/myapp/config</span></span></code></pre></div><p>Token scope syntax and matching rules are documented in detail under <a href="/pika/guide/tokens-and-scopes">Tokens &amp; scopes</a>.</p><h2 id="external-authentication" tabindex="-1">External authentication <a class="header-anchor" href="#external-authentication" aria-label="Permalink to “External authentication”">​</a></h2><p>Pika supports two external strategies, both configurable from <strong>Settings → Authentication</strong> at runtime:</p><table tabindex="0"><thead><tr><th>Strategy</th><th>What it does</th></tr></thead><tbody><tr><td><strong>OAuth2 / OIDC</strong></td><td>Standard authorization-code flow with any compatible provider (Keycloak, Auth0, Okta, Azure AD, Google, …).</td></tr><tr><td><strong>Forward-auth</strong></td><td>Trust headers set by an upstream gateway (Turna, Authelia, Authentik, oauth2-proxy, …). Pika sees <code>X-User</code>, etc.</td></tr></tbody></table><p>When any external strategy is enabled, pika uses a <strong>session-first</strong> approach:</p><ol><li>If the request has a valid local session cookie, the user is authenticated immediately.</li><li>If no session cookie is present, pika delegates to the configured external strategy.</li><li>If neither succeeds, the request gets a 401.</li></ol><p>Local login always works — even when external auth is on. The <code>/api/v1/info</code> endpoint is always public so the SPA can boot and show the login screen regardless of the external strategy&#39;s redirect behaviour.</p><p>For OAuth2/OIDC providers, configure the provider&#39;s Authorization URL and Token URL explicitly (password flow only needs Token URL). For manual identity resolution, configure <strong>JWKS URL</strong> (<code>jwks_url</code>) to verify the provider&#39;s <code>id_token</code>, or <strong>UserInfo URL</strong> (<code>userinfo_url</code>) to fetch identity claims with the upstream access token when no JWKS URL is configured. Do not leave both blank: unverified token claims are not a secure identity source.</p><p>Get endpoint values from your trusted provider&#39;s <code>.well-known/openid-configuration</code> document: <code>authorization_endpoint</code>, <code>token_endpoint</code>, <code>userinfo_endpoint</code>, and <code>jwks_uri</code> (the value to use for JWKS URL). Consult the provider&#39;s documentation for its discovery location, including any tenant or realm path; there is no universal JWKS URL to guess. Existing legacy <code>issuer_url</code> configurations continue using discovery until manual endpoints are supplied.</p><p>The upstream access token is revoked best-effort after identity resolution. pika then issues its own session token.</p><p>OAuth2 providers are fail-closed by default: an incoming <code>(provider, subject)</code> must already be linked to a pika user, or match an existing verified email when email auto-linking is enabled. Enable <strong>Auto-create users</strong> on a provider if unknown identities should create external-only pika users at first login. Username selection for those users is <code>preferred_username</code>, then email local-part, then a subject-based fallback.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Strategies are hot-swapped via an <a href="https://rakunlabs.github.io/ada/guide/runtime-reload.html" target="_blank" rel="noreferrer">ada Slot</a>. Toggling them on/off or changing the OIDC client secret does not require a restart.</p></div><h2 id="external-permissions" tabindex="-1">External permissions <a class="header-anchor" href="#external-permissions" aria-label="Permalink to “External permissions”">​</a></h2><p>Externally-authenticated users can be linked to local <code>users</code> rows by verified email auto-linking or OAuth2 auto-create. If no row is linked, they have <strong>no enforced permission checks</strong> beyond declarative role/scope mappings and the superadmin allowlist.</p><p>Enable enforcement under <strong>Settings → Authentication → Permissions</strong>, then map external groups (or OAuth2 scopes) to pika capabilities:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pika-editor  →  files.read, files.write, external.read</span></span>
<span class="line"><span>auditors     →  files.read, external.read, tokens.manage</span></span></code></pre></div><p>If your gateway emits <code>X-Groups: pika-editor,auditors</code> for a user, the user gets the <strong>union</strong> of both sets. Unknown groups are ignored. Users not in the Superadmins allowlist and without any matching group are denied any restricted action (403).</p><p>The header name and value separator are configurable. Pika also accepts repeated header lines as a single concatenated list. The same role/scope mapping applies to OAuth2 token claims.</p>`,35)])])}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
